import styles from './CopilotCodeGuidelinesPlayground.module.css'

import {testIdProps} from '@github-ui/test-id-props'
import {Link} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import Header from './components/Header'
import GuidelineForm from './components/GuidelineForm'
import Sample from './components/Sample'
import {PlaygroundContextProvider} from './PlaygroundContext'
import type {CodingGuideline, CodingGuidelinePath} from './PlaygroundContext'

export interface CopilotCodeGuidelinesPlaygroundProps {
  indexPath: string
  playgroundRunsPath: string
  saveCodeGuidelinePath: string
  sampleCodeGenerationsPath: string
  codingGuideline: CodingGuideline
  promptCharLimit: number
  codingGuidelinePaths: CodingGuidelinePath[]
  showTabBar: boolean
  occurrencesPath: string
  featureIsDisabled: boolean
}

export function CopilotCodeGuidelinesPlayground({
  indexPath,
  playgroundRunsPath,
  saveCodeGuidelinePath,
  sampleCodeGenerationsPath,
  codingGuideline,
  promptCharLimit,
  codingGuidelinePaths,
  showTabBar,
  occurrencesPath,
  featureIsDisabled,
}: CopilotCodeGuidelinesPlaygroundProps) {
  return (
    <PlaygroundContextProvider
      initialCodingGuideline={codingGuideline}
      indexPath={indexPath}
      sampleCodeGenerationsPath={sampleCodeGenerationsPath}
      saveCodeGuidelinePath={saveCodeGuidelinePath}
      promptCharLimit={promptCharLimit}
      initialCodingGuidelinePaths={codingGuidelinePaths}
      showTabBar={showTabBar}
      occurrencesPath={occurrencesPath}
      featureIsDisabled={featureIsDisabled}
    >
      <CopilotCodeGuidelinesPlaygroundContent
        playgroundRunsPath={playgroundRunsPath}
        featureIsDisabled={featureIsDisabled}
      />
    </PlaygroundContextProvider>
  )
}

function CopilotCodeGuidelinesPlaygroundContent({
  playgroundRunsPath,
  featureIsDisabled,
}: {
  playgroundRunsPath: string
  featureIsDisabled: boolean
}) {
  return (
    <>
      <Header />
      <div className={`mt-3 d-flex flex-column flex-lg-row gap-3 ${styles.container}`}>
        <GuidelineForm />
        {featureIsDisabled ? <FeatureIsDisabled /> : <Sample playgroundRunsPath={playgroundRunsPath} />}
      </div>
    </>
  )
}

function FeatureIsDisabled() {
  return (
    <>
      <div
        className="flex-1 border rounded-2 d-flex flex-column flex-justify-center"
        {...testIdProps('blankslate-container')}
      >
        <Blankslate spacious>
          <Blankslate.Heading>Coding guidelines will be disabled September 1, 2025.</Blankslate.Heading>
          <Blankslate.Description>
            The coding guidelines playground is no longer available, but your existing guidelines will continue to run
            as expected. You can read more about the deprecation in{' '}
            <Link
              inline
              href="https://github.blog/changelog/2025-07-18-upcoming-deprecations-and-changes-to-copilot-code-review"
            >
              our announcement.
            </Link>{' '}
            We’re transitioning to a more flexible approach using <code>copilot-instructions.md</code>, which offers
            better customization and long-term support. To get started, visit the{' '}
            <Link
              href="https://docs.github.com/copilot/how-tos/custom-instructions/adding-repository-custom-instructions-for-github-copilot"
              target="_blank"
              rel="noreferrer"
              inline
            >
              custom instructions documentation
            </Link>
            .
          </Blankslate.Description>
        </Blankslate>
      </div>
    </>
  )
}

try{ CopilotCodeGuidelinesPlayground.displayName ||= 'CopilotCodeGuidelinesPlayground' } catch {}
try{ CopilotCodeGuidelinesPlaygroundContent.displayName ||= 'CopilotCodeGuidelinesPlaygroundContent' } catch {}
try{ FeatureIsDisabled.displayName ||= 'FeatureIsDisabled' } catch {}